python3 -c "
import json
# count_8
with open('/root/schema-dag-extraction/artifacts/bcs_controlled_llama-3.1-70b-fp8/count_8/results_incremental.jsonl') as f:
    lines = [json.loads(l) for l in f if l.strip()]
batches = {}
for r in lines:
    bid = r['batch_id']
    if bid not in batches:
        batches[bid] = {'correct':0,'total':0,'bcs':r['batch_bcs'],'group':r['group']}
    batches[bid]['total'] += 1
    if r['prediction'] == r['ground_truth']:
        batches[bid]['correct'] += 1
for bid,v in batches.items():
    v['accuracy'] = v['correct']/v['total']
    print(f'count_8 {bid} group={v[\"group\"]} bcs={v[\"bcs\"]:.4f} acc={v[\"accuracy\"]:.4f}')
"

